import type { ProjectId } from "./projects";

/**
 * Team roster. One entry per person; a person can hold roles in more than one project.
 *
 * To move someone to "Past Members": set that role's `status` to "former" and add an `end` date.
 * Dates are "YYYY-MM" (or just "YYYY" if the month is unknown).
 * `photo` is a file in public/images/team (generated by `npm run images`); omit it to show a placeholder.
 */
export type Role = {
  project: ProjectId;
  position: string;
  status: "current" | "former";
  start?: string;
  end?: string;
};

export type Member = {
  id: string;
  name: string;
  photo?: string;
  credentials: string[];
  roles: Role[];
};

